"use client";

import React, { useState, useEffect } from 'react';
import { Check, Shield, Zap, Crown, Lock, Code, Headphones, Rocket, Sparkles } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '@/lib/supabase';
import { getPlanAvailability, PlanAvailability, PlanName } from '@/lib/founderAvailability';
import { getDisplayPricing, getCurrentPublicPricing } from '@/lib/waves';

const plans = [
    {
        id: "curioso",
        name: "Curioso",
        price: "€0",
        publicPrice: "€0",
        period: "14 giorni",
        description: "Trial gratuito",
        features: [
            "1 Clone AI",
            "100 msg",
            "1 Canale",
            "Watermark"
        ],
        icon: Sparkles,
        color: "text-charcoal/60",
        bg: "bg-white",
        btn: "bg-champagne border border-charcoal/10 text-charcoal hover:bg-charcoal hover:text-white"
    },
    {
        id: "esploratore",
        name: "Esploratore",
        price: "€39",
        publicPrice: "€79",
        period: "/mese",
        description: "Per testare il potenziale",
        features: [
            "1 Clone AI",
            "1K msg/mese",
            "1 Canale",
            "Email Support <48h"
        ],
        icon: Zap,
        color: "text-blue-600",
        bg: "bg-gradient-to-br from-blue-50 to-indigo-50",
        btn: "bg-blue-600 text-white hover:bg-blue-700",
        popular: true
    },
    {
        id: "pioniere",
        name: "Pioniere",
        price: "€147",
        publicPrice: "€297",
        period: "/mese",
        description: "Il più scelto dai Coach",
        features: [
            "1 Clone AI",
            "5K msg/mese",
            "3 Canali",
            "A/B Test (20%)"
        ],
        icon: Zap,
        color: "text-gold",
        bg: "bg-gradient-to-br from-gold/5 to-gold/15",
        btn: "gold-gradient text-white shadow-lg",
        glow: true,
        popular: true
    },
    {
        id: "conquistatore",
        name: "Conquistatore",
        price: "€347",
        publicPrice: "€697",
        period: "/mese",
        description: "Per agenzie e power users",
        features: [
            "3 Cloni AI",
            "20K msg/mese",
            "Priority Support",
            "API Access"
        ],
        icon: Crown,
        color: "text-gold",
        bg: "bg-gradient-to-br from-champagne to-white",
        btn: "bg-charcoal text-white hover:bg-gold transition-all shadow-luxury"
    },
    {
        id: "imperatore",
        name: "Imperatore",
        price: "€697",
        publicPrice: "€1.197",
        period: "/mese",
        description: "Il trono digitale",
        features: [
            "10 Cloni AI",
            "50K msg/mese",
            "White-label",
            "Account Manager"
        ],
        icon: Crown,
        color: "text-white/80",
        bg: "gold-gradient !border-transparent",
        btn: "bg-white text-gold hover:bg-champagne transition-all shadow-luxury",
        isDark: true
    }
];

export default function BillingPage() {
    const [loading, setLoading] = useState<string | null>(null);
    const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
    const [availability, setAvailability] = useState<Record<string, PlanAvailability> | null>(null);
    const [displayPricing, setDisplayPricing] = useState<any>(null);

    useEffect(() => {
        async function fetchData() {
            const [availData, pricingData] = await Promise.all([
                getPlanAvailability(),
                getDisplayPricing()
            ]);
            setAvailability(availData);
            setDisplayPricing(pricingData);
        }
        fetchData();
    }, []);

    const handleSubscribe = async (planId: string) => {
        if (planId === 'curioso') return;
        setLoading(planId);
        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) {
                window.location.href = '/auth/login';
                return;
            }

            // Real-time check if still eligible for founder
            const currentAvail = await getPlanAvailability();
            const isSoldOut = currentAvail[planId as PlanName]?.isSoldOut || false;

            const response = await fetch('/api/stripe/checkout', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    plan: planId,
                    userId: user.id,
                    billing: 'monthly',
                    priceId: displayPricing?.stripePriceIds?.[planId]
                })
            });
            const data = await response.json();
            if (data.url) {
                window.location.href = data.url;
            } else {
                throw new Error(data.error);
            }
        } catch (error) {
            console.error("Sub Error:", error);
            alert("Errore durante l'avvio del checkout.");
        } finally {
            setLoading(null);
        }
    };

    return (
        <div className="p-4 lg:p-8 min-h-screen bg-transparent overflow-hidden">
            <header className="text-center mb-12 max-w-4xl mx-auto">
                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="flex items-center justify-center gap-6 mb-3"
                >
                    <span className="h-[1px] w-10 bg-gold/30"></span>
                    <span className="text-gold text-[8px] lg:text-[10px] uppercase tracking-[1em] font-black italic shadow-gold">COMMERCE ENGINE</span>
                    <span className="h-[1px] w-10 bg-gold/30"></span>
                </motion.div>

                <motion.h1
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.8 }}
                    className="font-serif text-3xl lg:text-7xl italic text-charcoal leading-none tracking-tight mb-6"
                >
                    La tua <span className="gold-text-gradient">Sovranità</span> d'Elite.
                </motion.h1>

                <motion.p
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: 0.5 }}
                    className="text-charcoal/40 font-serif italic text-base border-x border-gold/10 px-8 lg:px-12"
                >
                    "Il lusso non è un'opzione, è uno standard. Solo per i primi Founder."
                </motion.p>
            </header>

            <div className="flex flex-col lg:flex-row gap-3 h-auto lg:h-[520px] max-w-full mx-auto items-stretch px-2 lg:px-4">
                {plans.map((p, i) => {
                    const isHovered = hoveredIndex === i;
                    const isAnyHovered = hoveredIndex !== null;
                    const planAvail = availability?.[p.id];
                    const isSoldOut = planAvail?.isSoldOut || false;

                    const publicPrice = getCurrentPublicPricing().prices[p.id as keyof ReturnType<typeof getCurrentPublicPricing>['prices']];
                    const price = displayPricing?.prices?.[p.id as string] || 0;
                    const isFounderPrice = displayPricing?.tier === 'founder';

                    return (
                        <motion.div
                            key={i}
                            onMouseEnter={() => setHoveredIndex(i)}
                            onMouseLeave={() => setHoveredIndex(null)}
                            animate={{
                                flex: isHovered ? 2.2 : isAnyHovered ? 0.85 : 1,
                                filter: isAnyHovered && !isHovered ? 'blur(1px) grayscale(0.6)' : 'none',
                                opacity: isAnyHovered && !isHovered ? 0.6 : 1,
                                scale: isHovered ? 1.02 : 1
                            }}
                            className={`silk-card p-5 lg:p-7 rounded-[2.5rem] border border-white/60 flex flex-col relative overflow-hidden transition-all duration-500 cursor-pointer ${p.bg} shadow-luxury-sm hover:shadow-luxury`}
                        >
                            {isSoldOut ? (
                                <div className="absolute top-5 right-5 flex items-center gap-2 bg-charcoal/80 px-2.5 py-1 rounded-full border border-white/10 z-20">
                                    <span className="text-[6px] text-white font-black uppercase tracking-widest leading-none">SOLD OUT</span>
                                </div>
                            ) : p.popular && (
                                <div className="absolute top-5 right-5 flex items-center gap-2 bg-gold/10 px-2.5 py-1 rounded-full border border-gold/20 z-20">
                                    <Zap className="w-2 h-2 text-gold" />
                                    <span className="text-[6px] text-gold font-black uppercase tracking-widest leading-none">PIÙ AMATO</span>
                                </div>
                            )}

                            <div className="flex-grow flex flex-col min-w-[150px]">
                                <div className="flex items-center gap-2 mb-3">
                                    <div className={`p-2 rounded-xl glass-card ${p.isDark ? 'bg-white/10' : 'bg-gold/5 text-gold'}`}>
                                        <p.icon className="w-4 h-4" />
                                    </div>
                                    <p className={`text-[8px] lg:text-[10px] uppercase tracking-[0.4em] font-black ${p.isDark ? 'text-white/60' : 'text-charcoal/30'}`}>
                                        {p.name}
                                    </p>
                                </div>

                                <div className="flex flex-col mb-4">
                                    <div className="flex items-baseline gap-1">
                                        <span className={`text-3xl lg:text-5xl font-serif tracking-tighter ${p.isDark ? 'text-white' : 'text-charcoal'}`}>€{price}</span>
                                        <span className={`text-[8px] lg:text-[9px] uppercase tracking-widest opacity-40 font-bold ${p.isDark ? 'text-white' : 'text-charcoal'}`}>{p.period}</span>
                                    </div>
                                    {!isSoldOut && p.id !== 'curioso' && isFounderPrice && (
                                        <div className="flex items-center gap-2 mt-1">
                                            <span className={`text-[9px] line-through opacity-30 ${p.isDark ? 'text-white' : 'text-charcoal'}`}>€{publicPrice}</span>
                                            <span className="text-[8px] bg-gold/10 text-gold px-1.5 py-0.5 rounded-md font-bold uppercase tracking-tight">FOUNDER</span>
                                        </div>
                                    )}
                                    {(!isFounderPrice || isSoldOut) && p.id !== 'curioso' && (
                                        <div className="mt-1">
                                            <span className="text-[7px] uppercase tracking-widest font-black opacity-30">Prezzo Pubblico Attivo</span>
                                        </div>
                                    )}
                                </div>

                                <motion.p
                                    className={`text-[10px] lg:text-[11px] italic font-serif leading-relaxed mb-6 h-10 overflow-hidden ${p.isDark ? 'text-white/60' : 'text-charcoal/40'}`}
                                >
                                    {p.description}
                                </motion.p>

                                <AnimatePresence>
                                    {isHovered && (
                                        <motion.div
                                            initial={{ opacity: 0, scale: 0.95 }}
                                            animate={{ opacity: 1, scale: 1 }}
                                            exit={{ opacity: 0, scale: 0.95 }}
                                            className="space-y-2 flex-grow py-3 border-t border-gold/5"
                                        >
                                            {p.features.slice(0, 8).map((f, j) => (
                                                <div key={j} className="flex items-start gap-2">
                                                    <div className={`mt-1 w-3 h-3 rounded-full flex items-center justify-center shrink-0 ${p.isDark ? 'bg-white/20 text-white' : 'bg-gold/10 text-gold shadow-sm'}`}>
                                                        <Check className="w-1.5 h-1.5" />
                                                    </div>
                                                    <span className={`text-[8px] lg:text-[9.5px] uppercase tracking-wider font-bold leading-tight ${p.isDark ? 'text-white/80' : 'text-charcoal/70'}`}>{f}</span>
                                                </div>
                                            ))}
                                        </motion.div>
                                    )}
                                </AnimatePresence>
                            </div>

                            <motion.div
                                className="mt-auto pt-3"
                                animate={{
                                    opacity: isHovered ? 1 : 0.8,
                                    y: isHovered ? 0 : 5
                                }}
                            >
                                <button
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        handleSubscribe(p.id);
                                    }}
                                    disabled={loading === p.id}
                                    className={`w-full py-3.5 rounded-full text-[8px] lg:text-[9px] uppercase tracking-[0.4em] font-black transition-all duration-500 border overflow-hidden ${p.btn}`}
                                >
                                    {loading === p.id
                                        ? '...'
                                        : p.id === 'curioso'
                                            ? 'ACTIVE'
                                            : isHovered ? (isSoldOut ? 'GET ELITE ACCESS' : `ACTIVATE FOUNDER ${p.name}`) : (isSoldOut ? 'Join the Elite' : `Scegli ${p.name}`)}
                                </button>
                            </motion.div>
                        </motion.div>
                    );
                })}
            </div>

            <footer className="mt-12 grid grid-cols-1 md:grid-cols-3 gap-6 max-w-4xl mx-auto opacity-30 hover:opacity-100 transition-opacity duration-1000 px-6">
                {[
                    { icon: Lock, title: "Sovereign Vault", desc: "Protocolli d'élite." },
                    { icon: Code, title: "Custom Logic", desc: "API d'Impresa." },
                    { icon: Headphones, title: "Concierge 24/7", desc: "Al tuo fianco." }
                ].map((item, idx) => (
                    <div key={idx} className="flex items-center gap-3">
                        <div className="w-10 h-10 glass-card rounded-lg flex items-center justify-center text-gold border border-gold/10 shadow-sm">
                            <item.icon className="w-4 h-4" />
                        </div>
                        <div>
                            <p className="text-[8px] uppercase tracking-[0.3em] font-black text-charcoal">{item.title}</p>
                            <p className="text-[10px] italic font-serif text-charcoal/60">{item.desc}</p>
                        </div>
                    </div>
                ))}
            </footer>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Crown, Zap, Clock, Users, ArrowRight, Check, Star, Loader2, Shield, Lock } from 'lucide-react';
import { getCurrentWave, getCurrentWaveSpotsRemaining, getDisplayPricing, getCurrentPublicPricing, getTotalFounderSpots, getFoundersSold, Wave } from '@/lib/waves';

export default function FounderPage() {
    const [spotsLeft, setSpotsLeft] = useState(20);
    const [totalSpots, setTotalSpots] = useState(60);
    const [timeLeft, setTimeLeft] = useState({ days: 0, hours: 0, minutes: 0, seconds: 0 });
    const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
    const [currentWave, setCurrentWave] = useState<Wave | null>(null);
    const [isSoldOut, setIsSoldOut] = useState(false);
    const [displayPricing, setDisplayPricing] = useState<any>(null);
    const [isFounderOpen, setIsFounderOpen] = useState(true);

    useEffect(() => {
        async function fetchData() {
            const [wave, remaining, allPricing, total] = await Promise.all([
                getCurrentWave(),
                getCurrentWaveSpotsRemaining(),
                getDisplayPricing(),
                getTotalFounderSpots()
            ]);

            setCurrentWave(wave);
            setSpotsLeft(remaining);
            setDisplayPricing(allPricing);
            setTotalSpots(total);
            setIsSoldOut(!wave);

            // Hardcoded deadline for UI (31 March 2026)
            const deadline = new Date('2026-03-31T23:59:59');
            const now = new Date();
            const diff = deadline.getTime() - now.getTime();
            if (diff > 0) {
                setTimeLeft({
                    days: Math.floor(diff / (1000 * 60 * 60 * 24)),
                    hours: Math.floor((diff / (1000 * 60 * 60)) % 24),
                    minutes: Math.floor((diff / (1000 * 60)) % 60),
                    seconds: Math.floor((diff / 1000) % 60),
                });
            }
        }
        fetchData();
        const interval = setInterval(fetchData, 30000);
        return () => clearInterval(interval);
    }, []);

    // 👑 IMPERIAL PRICING PLANS
    const publicPricing = getCurrentPublicPricing();

    const plans = [
        {
            id: 'esploratore',
            name: 'Esploratore',
            icon: '⚡',
            priceFounder: displayPricing?.prices?.esploratore || 39,
            pricePublic: publicPricing.prices.esploratore,
            pricePublicFinal: 397,
            features: ['1 Clone AI', '1,000 msg/mese', '1 Canale', 'Email Support <48h'],
        },
        {
            id: 'pioniere',
            name: 'Pioniere',
            icon: '🚀',
            priceFounder: displayPricing?.prices?.pioniere || 147,
            pricePublic: publicPricing.prices.pioniere,
            pricePublicFinal: 797,
            featured: true,
            badge: 'PIÙ SCELTO',
            features: ['1 Clone AI', '5,000 msg/mese', '3 Canali', 'A/B Testing 20%', 'Analytics Pro'],
        },
        {
            id: 'conquistatore',
            name: 'Conquistatore',
            icon: '💎',
            priceFounder: displayPricing?.prices?.conquistatore || 347,
            pricePublic: publicPricing.prices.conquistatore,
            pricePublicFinal: 1397,
            features: ['3 Cloni AI', '20,000 msg/mese', 'API Access (60 req/min)', 'Priority Support'],
        },
        {
            id: 'imperatore',
            name: 'Imperatore',
            icon: '👑',
            priceFounder: displayPricing?.prices?.imperatore || 697,
            pricePublic: publicPricing.prices.imperatore,
            pricePublicFinal: 2197,
            features: ['10 Cloni AI', '50K msg/mese', 'White-label', 'Account Manager', 'API Priority'],
        },
    ];

    // Function to calculate 5-year savings for Founder plans
    const calculateFounderSavings = (planId: string) => {
        const plan = plans.find(p => p.id === planId);
        if (!plan) return 0;
        return (plan.pricePublicFinal - plan.priceFounder) * 60; // 60 months in 5 years
    };

    // Direct checkout - Dynamic tier based on availability
    const handleCheckout = async (planId: string) => {
        setLoadingPlan(planId);

        try {
            const response = await fetch('/api/stripe/checkout', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    plan: planId,
                    priceId: displayPricing?.stripePriceIds?.[planId]
                }),
            });

            const data = await response.json();

            if (data.error) {
                alert(`Errore: ${data.error}`);
                return;
            }

            if (data.url) {
                window.location.href = data.url;
            }
        } catch (error) {
            console.error('Checkout error:', error);
            alert('Errore durante il checkout. Riprova.');
        } finally {
            setLoadingPlan(null);
        }
    };

    return (
        <div className="min-h-screen bg-champagne">
            {/* Top Banner */}
            <div className="bg-charcoal text-white text-center py-3 text-sm font-medium">
                {!isSoldOut ? (
                    <>
                        <span className="animate-pulse">🔥</span> {currentWave?.nameFull} · Solo {spotsLeft} Posti Rimasti · Chiusura: 31 Marzo 2026 · Prezzo Bloccato LIFETIME
                    </>
                ) : (
                    <>
                        <Lock className="w-4 h-4 inline-block mr-2" />
                        Programma Founder Chiuso · I Prezzi Pubblici Sono Ora Attivi
                    </>
                )}
            </div>

            {/* Main Container */}
            <div className="max-w-6xl mx-auto px-4 py-12 lg:py-20">

                {/* Hero Section */}
                <div className="text-center mb-16">
                    <div className={`inline-flex items-center gap-2 ${isFounderOpen ? 'bg-gold/10 text-gold' : 'bg-charcoal/10 text-charcoal'} px-6 py-2 rounded-full mb-8 font-black text-[10px] uppercase tracking-[0.4em]`}>
                        <Crown className="w-4 h-4" />
                        {isFounderOpen ? 'Founder Program Sovereign Edition' : 'VirtualTwin Public Pricing'}
                    </div>

                    <h1 className="font-serif text-5xl md:text-7xl mb-6 leading-tight text-charcoal">
                        {isFounderOpen ? (
                            <>
                                Blocca il Prezzo<br />
                                <span className="italic gold-text-gradient">Per Sempre.</span>
                            </>
                        ) : (
                            <>
                                Il Tuo Clone AI<br />
                                <span className="italic text-charcoal/70">Ti Aspetta.</span>
                            </>
                        )}
                    </h1>

                    <p className="text-xl md:text-2xl text-charcoal/60 max-w-3xl mx-auto leading-relaxed">
                        {isFounderOpen ? (
                            <>
                                Entra nei primi <strong className="text-charcoal">{totalSpots} Founder</strong> e blocca il prezzo
                                a <strong className="text-gold">€{displayPricing?.prices?.pioniere || 147}/mese</strong> per sempre.
                                <br className="hidden md:block" />
                                Anche quando il prezzo pubblico aumenterà a €{plans[1].pricePublicFinal}/mese.
                            </>
                        ) : (
                            <>
                                Scegli il piano perfetto per il tuo business.
                                <br className="hidden md:block" />
                                Inizia con <strong className="text-charcoal">14 giorni di trial gratuito</strong>.
                            </>
                        )}
                    </p>
                </div>

                {/* Countdown Section - Only show if Founder open */}
                {isFounderOpen && (
                    <div className="bg-gradient-to-br from-charcoal to-charcoal/90 border border-gold/20 rounded-[2rem] p-10 mb-16 text-center shadow-2xl">
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-8">
                            {[
                                { value: timeLeft.days, label: 'Giorni' },
                                { value: timeLeft.hours, label: 'Ore' },
                                { value: timeLeft.minutes, label: 'Minuti' },
                                { value: timeLeft.seconds, label: 'Secondi' },
                            ].map((item, i) => (
                                <div key={i} className="bg-white/5 rounded-xl p-4">
                                    <div className="text-4xl md:text-5xl font-bold text-gold font-mono">
                                        {String(item.value).padStart(2, '0')}
                                    </div>
                                    <div className="text-white/50 text-xs uppercase tracking-wider mt-1">{item.label}</div>
                                </div>
                            ))}
                        </div>

                        <div className="flex flex-col md:flex-row justify-center items-center gap-8">
                            <div className="flex items-center gap-3">
                                <Users className="w-6 h-6 text-gold" />
                                <div>
                                    <span className="text-3xl font-bold text-gold">{spotsLeft}</span>
                                    <span className="text-white/60 text-lg">/{totalSpots} posti</span>
                                </div>
                            </div>
                            <div className="hidden md:block w-px h-10 bg-white/20" />
                            <div className="flex items-center gap-3">
                                <Star className="w-6 h-6 text-gold" />
                                <div>
                                    <span className="text-3xl font-bold text-gold">€{calculateFounderSavings('imperatore').toLocaleString()}</span>
                                    <span className="text-white/60 text-lg"> risparmio 5 anni</span>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* Pricing Grid */}
                <div id="pricing" className="grid md:grid-cols-2 lg:grid-cols-4 gap-4 mb-16 scroll-mt-8">
                    {plans.map((plan, i) => (
                        <div
                            key={i}
                            className={`relative rounded-[1.5rem] p-6 border-2 transition-all ${plan.featured
                                ? 'bg-gradient-to-br from-gold/10 to-champagne border-gold shadow-xl scale-[1.02]'
                                : plan.id === 'imperatore'
                                    ? 'bg-charcoal text-white border-gold shadow-xl'
                                    : 'bg-white border-charcoal/10 hover:border-gold/50'
                                }`}
                        >
                            {/* SOLD OUT Badge when Genesis exhausted */}
                            {isSoldOut && (
                                <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-red-500 text-white px-4 py-1 rounded-full text-[9px] font-black uppercase tracking-wider z-10">
                                    🔴 SOLD OUT
                                </div>
                            )}

                            {/* Popular Badge - only when founder open */}
                            {plan.badge && isFounderOpen && !isSoldOut && (
                                <div className="absolute -top-3 left-1/2 -translate-x-1/2 gold-gradient text-white px-4 py-1 rounded-full text-[9px] font-black uppercase tracking-wider">
                                    {plan.badge}
                                </div>
                            )}

                            <div className="text-4xl mb-3">{plan.icon}</div>
                            <h3 className="text-xl font-bold mb-4">{plan.name}</h3>

                            <div className="mb-4">
                                <div className={`text-4xl font-bold mb-1 text-gold`}>
                                    €{isFounderOpen ? plan.priceFounder : plan.pricePublic}
                                </div>
                                {isFounderOpen && (
                                    <>
                                        <div className={`text-sm line-through ${plan.id === 'imperatore' ? 'text-white/40' : 'text-charcoal/40'}`}>
                                            €{plan.pricePublic} pubblico 2026
                                        </div>
                                        <div className={`text-xs ${plan.id === 'imperatore' ? 'text-white/30' : 'text-charcoal/30'}`}>
                                            ↗ Aumenta ogni trimestre
